/**
 * Token-template ⇆ `inputs_fields` for the subscription "What the agent gets" composer.
 *
 * A non-technical user writes a message and drops in event fields as `{{path}}` tokens.
 * We compile that to a backend-resolvable `inputs_fields`: a chat user message (or the
 * completion agent's primary input) whose `content` is EITHER a single string (one literal
 * or one `$.selector`) OR an array of text parts — literal runs kept, `$.selector` runs
 * resolved leaf-by-leaf at delivery by `resolve_target_fields`. No backend change: it's the
 * same whole-string-or-literal leaf resolution, just structured as parts.
 *
 * Display ≠ storage: the editor shows `{{event.attributes.body}}`; we store
 * `{type:"text", text:"$.event.attributes.body"}`.
 */

export interface TemplateSegment {
    literal?: string
    selector?: string
}

// `{{ path }}` tokens. The inner path is a JSONPath/Pointer or a dot path (→ `$.path`).
// No \s* around the capture (ReDoS-ambiguous with [^{}]); `tokenToSelector` trims instead.
const TOKEN_RE = /\{\{([^{}]+)\}\}/g

function tokenToSelector(token: string): string {
    const t = token.trim()
    if (!t) return ""
    if (t.startsWith("$") || t.startsWith("/")) return t
    return `$.${t}`
}

function selectorToToken(selector: string): string {
    if (selector === "$") return "{{$}}"
    if (selector.startsWith("$.")) return `{{${selector.slice(2)}}}`
    return `{{${selector}}}`
}

/** Split a template string into literal + selector segments (in order). */
export function splitTemplate(template: string): TemplateSegment[] {
    const segments: TemplateSegment[] = []
    let last = 0
    let m: RegExpExecArray | null
    TOKEN_RE.lastIndex = 0
    while ((m = TOKEN_RE.exec(template)) !== null) {
        if (m.index > last) segments.push({literal: template.slice(last, m.index)})
        const selector = tokenToSelector(m[1])
        if (selector) segments.push({selector})
        last = m.index + m[0].length
    }
    if (last < template.length) segments.push({literal: template.slice(last)})
    return segments
}

// Segments → a message `content`: "" when empty, a bare string when there's a single
// literal/selector, else an array of resolvable text parts.
function segmentsToContent(segments: TemplateSegment[]): string | {type: "text"; text: string}[] {
    const nonEmpty = segments.filter((s) => (s.selector ?? s.literal ?? "") !== "")
    if (nonEmpty.length === 0) return ""
    if (nonEmpty.length === 1) return nonEmpty[0].selector ?? nonEmpty[0].literal ?? ""
    return nonEmpty.map((s) => ({type: "text" as const, text: s.selector ?? s.literal ?? ""}))
}

/**
 * Compile a token template into `inputs_fields`. Chat agents → a `messages` user message;
 * completion agents → the primary input key. Empty template → `{}`.
 */
export function compileMessageTemplate(
    template: string,
    isChat: boolean,
    primaryKey: string,
): Record<string, unknown> {
    if (!template.trim()) return {}
    const content = segmentsToContent(splitTemplate(template))
    if (content === "") return {}
    if (isChat) return {messages: [{role: "user", content}]}
    return {[primaryKey]: content}
}

// A content value the composer can REPRODUCE: a plain string, or an array of strictly
// `{type:"text", text}` parts (what `segmentsToContent` emits). Returns the template, or null
// when not representable (an image/audio part, or a malformed object) so callers don't show —
// then silently collapse — a payload they can't round-trip.
function contentToTemplate(content: unknown): string | null {
    if (typeof content === "string") {
        return content.startsWith("$") || content.startsWith("/")
            ? selectorToToken(content)
            : content
    }
    if (Array.isArray(content)) {
        const parts: string[] = []
        for (const p of content) {
            if (
                !p ||
                typeof p !== "object" ||
                (p as {type?: unknown}).type !== "text" ||
                typeof (p as {text?: unknown}).text !== "string"
            ) {
                return null
            }
            const text = (p as {text: string}).text
            parts.push(text.startsWith("$") || text.startsWith("/") ? selectorToToken(text) : text)
        }
        return parts.join("")
    }
    return null
}

/**
 * Parse `inputs_fields` (serialized JSON) back into a token template for the editor. Returns ""
 * unless the mapping is EXACTLY what `compileMessageTemplate` emits — a single `{role:"user"}`
 * message (chat) / the one `primaryKey` (completion) with representable content, and no other
 * keys. Anything else (multi-message, system/assistant, non-text parts, extra keys) isn't
 * representable; the caller falls back to the raw-JSON Advanced editor instead of collapsing it.
 */
export function parseMessageTemplate(
    inputsText: string,
    isChat: boolean,
    primaryKey: string,
): string {
    let parsed: unknown
    try {
        parsed = inputsText.trim() ? JSON.parse(inputsText) : {}
    } catch {
        return ""
    }
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return ""
    const obj = parsed as Record<string, unknown>
    const keys = Object.keys(obj)
    if (isChat) {
        if (keys.length !== 1 || keys[0] !== "messages") return ""
        const messages = obj.messages
        if (!Array.isArray(messages) || messages.length !== 1) return ""
        const message = messages[0]
        if (!message || typeof message !== "object" || (message as {role?: string}).role !== "user")
            return ""
        return contentToTemplate((message as {content?: unknown}).content) ?? ""
    }
    if (keys.length !== 1 || keys[0] !== primaryKey) return ""
    return contentToTemplate(obj[primaryKey]) ?? ""
}
/**
 * Selector resolution for the subscription mapping preview.
 *
 * A subscription maps workflow inputs from the event context via selectors:
 * JSONPath-lite (`$.a.b[0]`, `$["a"]["b"]`) or JSON Pointer (`/a/b/0`). The
 * drawer resolves them against a sample context to preview what each field
 * would receive. Dependency-free and best-effort: an unresolved selector yields
 * `undefined` rather than throwing. The backend remains the source of truth.
 */

/** Render a resolved value for display. */
export function previewValue(value: unknown): string {
    if (typeof value === "string") return value
    try {
        return JSON.stringify(value)
    } catch {
        return String(value)
    }
}

/** Best-effort resolution of `$.a.b[0]` / `$["a"]["b"]` / `/a/b/0`. */
export function resolveSelectorPreview(selector: string, data: Record<string, unknown>): unknown {
    try {
        if (selector === "$") return data
        if (selector.startsWith("/")) {
            const tokens = selector
                .split("/")
                .slice(1)
                .map((t) => t.replace(/~1/g, "/").replace(/~0/g, "~"))
            return walk(data, tokens)
        }
        if (selector.startsWith("$")) {
            const tokens = selector
                .slice(1)
                .replace(/\[(\d+)\]/g, ".$1")
                .replace(/\[["'](.*?)["']\]/g, ".$1")
                .split(".")
                .filter((t) => t.length > 0)
            return walk(data, tokens)
        }
    } catch {
        return undefined
    }
    return undefined
}

function walk(data: unknown, tokens: string[]): unknown {
    let cur: unknown = data
    for (const token of tokens) {
        if (cur == null) return undefined
        if (Array.isArray(cur)) {
            const idx = Number(token)
            if (!Number.isInteger(idx)) return undefined
            cur = cur[idx]
        } else if (typeof cur === "object") {
            cur = (cur as Record<string, unknown>)[token]
        } else {
            return undefined
        }
    }
    return cur
}

/**
 * Friendly single "message" <-> a schedule's `inputs_fields`.
 *
 * A cron tick delivers `inputs_fields` verbatim as the agent's `inputs`. Chat agents
 * take a `messages` array; completion agents take their schema's named string inputs.
 * The composer edits one message; these pure helpers read/write it into the right
 * shape, preserving any other keys the user set via the raw-JSON editor.
 *
 * `isChat` and `primaryKey` are resolved by the caller from the bound agent's schema
 * (`workflowMolecule.selectors.isChat` + `extractInputPortsFromSchema`).
 */

function parseObject(inputsText: string): Record<string, unknown> {
    try {
        const parsed = inputsText.trim() ? JSON.parse(inputsText) : {}
        return parsed && typeof parsed === "object" && !Array.isArray(parsed)
            ? (parsed as Record<string, unknown>)
            : {}
    } catch {
        return {}
    }
}

/**
 * Parse the editor text into `inputs_fields`, enforcing the STORED shape: a non-array JSON
 * object (key → selector/literal/parts). Arrays/strings/numbers parse fine but break every
 * downstream reader (message composition, previews, the resolver's per-key walk), so reject
 * them at the save boundary instead of persisting an unreadable mapping.
 */
export function parseInputsFields(
    inputsText: string,
): {value: Record<string, unknown>; error?: undefined} | {value?: undefined; error: string} {
    const trimmed = inputsText.trim()
    if (!trimmed) return {value: {}}
    let parsed: unknown
    try {
        parsed = JSON.parse(trimmed)
    } catch {
        return {error: "Inputs mapping is not valid JSON"}
    }
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        return {error: "Inputs mapping must be a JSON object"}
    }
    return {value: parsed as Record<string, unknown>}
}

/**
 * Read a message's `content` as readable text. A trigger message's content is either a
 * plain string or an array of `{type:"text", text}` parts (the only way the resolver can
 * carry mixed literal + `$.selector` in one message — each whole leaf is resolved). Joins
 * the parts so previews and playground replays show real text, never a JSON blob.
 */
export function messageContentText(content: unknown): string {
    if (typeof content === "string") return content
    if (Array.isArray(content)) {
        return content
            .map((part) =>
                part && typeof part === "object" && "text" in part
                    ? String((part as {text?: unknown}).text ?? "")
                    : typeof part === "string"
                      ? part
                      : "",
            )
            .join("")
    }
    return ""
}

// A `messages` payload is self-describing, so it edits as chat even when the schema says
// completion — the bound agent may be unresolved, or the mapping written by the API.
function isMessagesPayload(obj: Record<string, unknown>): boolean {
    return Array.isArray(obj.messages)
}

/** Read the message out of `inputs_fields`. Empty string when absent or unparseable. */
export function getScheduleMessage(
    inputsText: string,
    isChat: boolean,
    primaryKey: string,
): string {
    // Representable only as the single user/string message `setScheduleMessage` writes (it
    // REPLACES `messages` wholesale, so a multi-message / non-user / non-string-content payload
    // would be collapsed on save). Extra top-level keys are fine — setScheduleMessage preserves
    // them. Not representable → "" so the caller falls back to the raw-JSON editor.
    const obj = parseObject(inputsText)
    if (isChat || isMessagesPayload(obj)) {
        const messages = obj.messages
        if (!Array.isArray(messages) || messages.length !== 1) return ""
        const message = messages[0]
        if (!message || typeof message !== "object" || (message as {role?: string}).role !== "user")
            return ""
        const content = (message as {content?: unknown}).content
        return typeof content === "string" ? content : ""
    }
    const value = obj[primaryKey]
    return typeof value === "string" ? value : ""
}

/** Write the message into `inputs_fields`, returning the serialized JSON. */
export function setScheduleMessage(
    inputsText: string,
    message: string,
    isChat: boolean,
    primaryKey: string,
): string {
    const obj = parseObject(inputsText)
    const trimmed = message.trim()
    // Mirrors the getter's shape check so an edit writes back where it was read from.
    if (isChat || isMessagesPayload(obj)) {
        if (trimmed) obj.messages = [{role: "user", content: message}]
        else delete obj.messages
    } else if (trimmed) {
        obj[primaryKey] = message
    } else {
        delete obj[primaryKey]
    }
    return Object.keys(obj).length ? JSON.stringify(obj, null, 2) : "{}"
}

/**
 * Rewrite the message into a new agent shape after the bound agent resolves.
 *
 * The drawers derive `isChat`/`primaryKey` from an async query, so a message typed before the
 * agent is known is stored under the wrong key. Re-reading it under the new shape yields "" —
 * the composer looks empty while `inputs_fields` still holds the old shape, which then saves
 * against an agent that can't receive it.
 *
 * `setScheduleMessage` alone can't do this: it preserves sibling keys, so writing under the new
 * shape would leave `{"message": "…", "messages": [...]}`. The old shape's key must go first.
 * A mapping the composer can't read is returned untouched — there's nothing safe to migrate.
 */
export function remapMessageShape(
    inputsText: string,
    prev: {isChat: boolean; primaryKey: string},
    next: {isChat: boolean; primaryKey: string},
): string {
    const message = getScheduleMessage(inputsText, prev.isChat, prev.primaryKey)
    if (!message) return inputsText
    const obj = parseObject(inputsText)
    if (prev.isChat || isMessagesPayload(obj)) delete obj.messages
    else delete obj[prev.primaryKey]
    return setScheduleMessage(JSON.stringify(obj), message, next.isChat, next.primaryKey)
}

/**
 * Best-effort message preview from a resolved `inputs_fields` object — for list rows
 * where the agent schema isn't handy. Reads the first chat user message, else the first
 * non-empty string value. Empty string when there's nothing to show.
 */
export function getScheduleMessagePreview(inputsFields: unknown): string {
    if (!inputsFields || typeof inputsFields !== "object" || Array.isArray(inputsFields)) return ""
    const obj = inputsFields as Record<string, unknown>
    if (Array.isArray(obj.messages)) {
        const msgs = obj.messages as unknown[]
        const user =
            (msgs.find(
                (m) => !!m && typeof m === "object" && (m as {role?: string}).role === "user",
            ) as {content?: unknown} | undefined) ?? (msgs[0] as {content?: unknown} | undefined)
        return messageContentText(user?.content)
    }
    for (const value of Object.values(obj)) {
        if (typeof value === "string" && value.trim()) return value
    }
    return ""
}
